recipes=[
{'id':'crab-mushrooms','title':'Crab-Stuffed Mushrooms','course':'Appetizer','seafood':['Crab'],'time':'18–20 min bake','method':'Oven · 375°F','intro':'Golden mushroom caps with a creamy lump-crab filling and a little panko crunch.','ingredients':['Mushroom caps','Softened cream cheese','Minced garlic','Grated Parmesan','Lemon juice','Old Bay seasoning','Chopped parsley','Lump crab meat','Panko breadcrumbs'],'steps':['Wipe the mushrooms clean, remove the stems, and gently scoop out a little of the inside to make room. Arrange on a parchment-lined baking sheet.','Mix cream cheese, garlic, Parmesan, lemon juice, Old Bay and parsley until smooth. Gently fold in the crab, keeping the lumps intact.','Fill each mushroom cap generously and sprinkle with panko.','Bake at 375°F for 18–20 minutes, until the mushrooms are tender and the tops golden. Serve warm.'],'note':'The email gives a method but no ingredient amounts or yield. Confirm quantities before cooking.'},
{'id':'calamari','title':'Fried Calamari','course':'Antipasto','seafood':['Calamari'],'time':'30 min soak + batch frying','method':'Fry · 375°F oil','intro':'Light, crisp rings and tentacles, finished with sea salt and fresh lemon.','ingredients':['Calamari rings and tentacles','Buttermilk','All-purpose flour','Cornstarch','Salt and pepper','Garlic powder','Paprika','Frying oil','Sea salt','Lemon wedges','Marinara or garlic aioli'],'steps':['Soak the calamari in buttermilk for about 30 minutes. Keep it refrigerated during the soak.','Whisk flour, cornstarch, salt, pepper, garlic powder and paprika together.','Heat frying oil in a deep skillet or Dutch oven to 375°F.','Dredge the calamari in the flour mixture, shaking off excess. Fry in small batches for about 1½–2 minutes, until lightly golden and crisp. Do not crowd the pan.','Drain, season immediately with sea salt, and serve hot with lemon and marinara or garlic aioli.'],'note':'Keep the soak refrigerated is an added handling note. Frying time is guidance from the email, not a substitute for checking doneness.'},
{'id':'seafood-pasta','title':'Seafood Linguine','course':'Main course','seafood':['Shrimp','Scallops','Clams','Mussels'],'time':'Cook just before serving','method':'Stovetop','intro':'Four kinds of seafood, white wine, cherry tomatoes and parsley in a glossy pan sauce.','ingredients':['Linguine','Salt','Olive oil','Butter','Minced garlic','Red pepper flakes','Clams','Mussels','White wine','Shrimp','Sea scallops','Cherry tomatoes, halved','Fresh parsley','Reserved pasta water — 1 cup'],'steps':['Cook linguine in salted water until just shy of al dente. Reserve 1 cup of pasta water before draining.','Warm olive oil and butter in a deep pan. Sauté garlic and red pepper flakes until fragrant, about 1 minute.','Add clams, mussels and white wine; cover for 3–5 minutes, until the shells open. Discard any that stay closed. Set the cooked shellfish aside.','The original email says to sear shrimp and scallops in the same pan for 1–2 minutes per side, then set them aside. See the practical adjustment below if you want a browned sear.','Toss cherry tomatoes and pasta in the pan juices. Add a little reserved pasta water until the sauce coats the noodles.','Gently fold in all the seafood. Finish with parsley and olive oil, and serve promptly.'],'note':'Practical adjustment: a wine-filled pan will simmer rather than sear. For browning, pat the scallops dry and sear them separately in a hot pan, then combine with the sauce. This is a suggested adjustment, not an instruction from the original email.'},
{'id':'flounder','title':'Breaded Flounder','course':'Main course','seafood':['Flounder'],'time':'About 5–7 min per batch','method':'Pan-fry','intro':'Delicate fillets in a crisp breadcrumb coating, served simply with lemon.','ingredients':['Flounder fillets','All-purpose flour','Eggs, beaten','Seasoned breadcrumbs','Salt and pepper','Olive oil','Butter','Lemon wedges'],'steps':['Set out three shallow dishes: flour, beaten eggs and seasoned breadcrumbs.','Pat the fillets dry and season lightly with salt and pepper. Coat in flour, dip in egg, then press into the breadcrumbs.','Heat olive oil and butter in a large skillet over medium-high heat.','Cook until golden, about 3–4 minutes on the first side, then carefully flip and cook for another 2–3 minutes. Check doneness; timing varies with thickness.','Drain on a wire rack or paper towel-lined plate. Serve immediately with lemon.'],'note':'The cooking times come from the email. Check the thickest part for doneness rather than relying on time alone.'}
]
